import csv
import io


def normalize_people(csv_text: str) -> list[dict[str, str]]:
    reader = csv.reader(io.StringIO(csv_text, newline=""))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV header must be name,email,age") from None
    normalized_header = [field.strip().lower() for field in header]
    if normalized_header != ["name", "email", "age"]:
        raise ValueError("CSV header must be name,email,age")

    people: list[dict[str, str]] = []
    for row in reader:
        line_number = reader.line_num
        if not row or all(not field.strip() for field in row):
            continue
        if len(row) != 3:
            raise ValueError(f"row {line_number} must have 3 columns")
        name, email, age = (field.strip() for field in row)
        if not name or not email:
            raise ValueError(f"row {line_number} requires name and email")
        local, separator, domain = email.partition("@")
        if (separator != "@" or not local or not domain or email.count("@") != 1
                or any(character.isspace() for character in email)):
            raise ValueError(f"row {line_number} has invalid email")
        if (not age.isascii() or not age.isdecimal()
                or not 0 <= int(age) <= 130):
            raise ValueError(f"row {line_number} has invalid age")
        people.append({"name": name, "email": email.lower(), "age": str(int(age))})
    return people
